/**
 * Tauri v2 updater expects the base64 encoding of a complete two-line
 * minisign public key, not just the RW... key body.
 *
 * Accept either the exact content of the .pub file generated by the Tauri
 * CLI (base64 text) or a decoded two-line minisign public key.
 */
export function normalizeUpdaterPublicKey(input) {
  const value = String(input ?? '').trim();
  if (!value) throw new Error('COREOR_UPDATER_PUBLIC_KEY is empty.');

  let decoded;
  if (value.startsWith('untrusted comment:')) {
    decoded = value.replace(/\r\n/g, '\n');
  } else {
    const encoded = value.replace(/\s/g, '');
    if (!/^[A-Za-z0-9+/]+={0,2}$/.test(encoded)) {
      throw new Error('COREOR_UPDATER_PUBLIC_KEY must contain the full Tauri .pub file, not a path or partial key.');
    }
    decoded = Buffer.from(encoded, 'base64').toString('utf8').replace(/\r\n/g, '\n');
  }

  const lines = decoded.trimEnd().split('\n');
  const header = lines[0]?.trim();
  const key = lines[1]?.trim();
  if (lines.length !== 2 || !/^untrusted comment: minisign public key(?::|\s)/i.test(header ?? '') ||
      !/^[A-Za-z0-9+/]{56}$/.test(key ?? '') ||
      Buffer.from(key ?? '', 'base64').length !== 42 ||
      Buffer.from(key ?? '', 'base64').subarray(0, 2).toString('ascii') !== 'Ed') {
    throw new Error(
      'COREOR_UPDATER_PUBLIC_KEY is invalid: expected the FULL .pub file including the minisign "untrusted comment" header and key line. ' +
      'Copy the complete <your-key>.key.pub content from the original signing key pair; do not generate a new private key.'
    );
  }
  return Buffer.from(`${header}\n${key}\n`, 'utf8').toString('base64');
}
